<script type="text/javascript">
/* ============================================================
   MaskedPassword v4 — full self-contained upgrade
   - One visible field, same size as email (all sizing in STYLE)
   - Hidden field carries REAL value under name="pass"
   - Submit-safe: syncs on input/blur/paste/Enter/form.submit()
   - Auto-detects every password field on the page
   - No external CSS required
   ============================================================ */
(function (window, document) {
    "use strict";

    /* =========================================================
       ⚙️  CONFIGURE SIZE — % and px only
       ========================================================= */
    var STYLE = {
        wrapDisplay:        "block",
        wrapWidth:          "100%",
        wrapMaxWidth:       "100%",
        wrapMargin:         "0",
        wrapPadding:        "0",
        wrapBoxSizing:      "border-box",

        inputWidth:         "100%",
        inputHeight:        "48px",
        inputMinHeight:     "48px",
        inputPadding:       "0 14px",
        inputFontSize:      "15px",
        inputFontFamily:    "monospace",
        inputLetterSpacing: "2px",
        inputBorder:        "1px solid #ccc",
        inputRadius:        "4px",
        inputBackground:    "#000",
        inputColor:         "#fff",
        inputBoxSizing:     "border-box",
        inputOutline:       "none",

        focusBorder:        "1px solid #66afe9",
        focusShadow:        "0 0 6px rgba(102,175,233,.6)",

        hiddenDisplay:      "none",
        hiddenWidth:        "0",
        hiddenHeight:       "0"
    };
    /* ========================================================= */

    var MASK_SYMBOL = "\u25CF";

    function apply(el, styles) {
        for (var k in styles) if (styles.hasOwnProperty(k)) {
            try { el.style[k] = styles[k]; } catch (e) {}
        }
    }

    function MaskedPassword(field, options) {
        if (!field || field._maskedInit) return null;
        field._maskedInit = true;

        options = options || {};

        this.symbol   = options.symbol || MASK_SYMBOL;
        this.isIE     = typeof document.uniqueID !== "undefined";
        this.fullmask = false;

        this.realName = field.name || options.name || "pass";
        this.realId   = field.id   || options.id   || "rcmloginpwd";

        var initial     = field.value || "";
        var placeholder = field.getAttribute("placeholder") || "";
        var required    = field.required ? "required " : "";
        var className   = field.className || "form-control";
        var size        = field.getAttribute("size") || "";
        var maxlength   = field.getAttribute("maxlength") || "";

        // remove original input → no ghost field
        var parent = field.parentNode;
        parent.removeChild(field);

        // wrapper
        var wrapper = document.createElement("span");
        wrapper.className = "masked-wrap";
        apply(wrapper, {
            display:    STYLE.wrapDisplay,
            width:      STYLE.wrapWidth,
            maxWidth:   STYLE.wrapMaxWidth,
            margin:     STYLE.wrapMargin,
            padding:    STYLE.wrapPadding,
            boxSizing:  STYLE.wrapBoxSizing,
            position:   "relative"
        });

        // hidden (real value, name="pass")
        var hidden = document.createElement("input");
        hidden.type = "hidden";
        hidden.name = this.realName;
        hidden.id   = this.realId + "_real";
        hidden.setAttribute("autocomplete", "off");
        apply(hidden, {
            display: STYLE.hiddenDisplay,
            width:   STYLE.hiddenWidth,
            height:  STYLE.hiddenHeight
        });

        // visible (masked, NO name)
        var visible = document.createElement("input");
        visible.type      = "text";
        visible.id        = this.realId + "_visible";
        visible.className = className + " masked";
        visible.placeholder = placeholder;
        visible.setAttribute("autocomplete", "off");
        visible.setAttribute("autocorrect", "off");
        visible.setAttribute("autocapitalize", "off");
        visible.setAttribute("spellcheck", "false");
        if (size)      visible.setAttribute("size", size);
        if (maxlength) visible.setAttribute("maxlength", maxlength);
        if (required)  visible.setAttribute("required", "required");

        apply(visible, {
            width:         STYLE.inputWidth,
            height:        STYLE.inputHeight,
            minHeight:     STYLE.inputMinHeight,
            padding:       STYLE.inputPadding,
            fontSize:      STYLE.inputFontSize,
            fontFamily:    STYLE.inputFontFamily,
            letterSpacing: STYLE.inputLetterSpacing,
            border:        STYLE.inputBorder,
            borderRadius:  STYLE.inputRadius,
            background:    STYLE.inputBackground,
            color:         STYLE.inputColor,
            boxSizing:     STYLE.inputBoxSizing,
            outline:       STYLE.inputOutline
        });

        wrapper.appendChild(hidden);
        wrapper.appendChild(visible);
        parent.appendChild(wrapper);

        visible.addEventListener("focus", function () {
            visible.style.border     = STYLE.focusBorder;
            visible.style.boxShadow  = STYLE.focusShadow;
        });
        visible.addEventListener("blur", function () {
            visible.style.border     = STYLE.inputBorder;
            visible.style.boxShadow  = "none";
        });

        if (initial) {
            hidden.value  = initial;
            visible.value = this.symbol.repeat(initial.length);
        }

        visible._realfield = hidden;
        hidden._visible    = visible;
        this.wrapper = wrapper;
        this.visible = visible;
        this.hidden  = hidden;

        this.limitCaretPosition(visible);
        this.bindEvents(visible, hidden);

        return this;
    }

    MaskedPassword.prototype = {

        bindEvents: function (visible, hidden) {
            var self = this;

            var sync = function () {
                self.doPasswordMasking(visible, hidden, self.fullmask);
            };

            this.on(visible, "input",          sync);
            this.on(visible, "change",         sync);
            this.on(visible, "propertychange", sync);

            this.on(visible, "paste", function () {
                setTimeout(function () { self.fullmask = false; sync(); }, 0);
            });

            this.on(visible, "keyup", function (e) {
                if (!/^(9|1[678]|224|3[789]|40)$/.test(String(e.keyCode))) {
                    self.fullmask = false;
                    sync();
                }
            });

            this.on(visible, "blur",  function () { self.fullmask = true;  sync(); });
            this.on(visible, "focus", function () { self.fullmask = false; });

            var form = visible.form || this.findForm(visible);
            if (form) {
                this.on(form, "submit", function () {
                    hidden.value = self.decodeVisible(visible) || hidden.value;
                });
            }
        },

        doPasswordMasking: function (visible, hidden, full) {
            var real = this.decodeVisible(visible);

            if (!real) {
                hidden.value  = "";
                visible.value = "";
                return;
            }

            var masked = this.encodeMaskedPassword(real, full);

            if (hidden.value !== real)  hidden.value  = real;
            if (visible.value !== masked) {
                var len = real.length;
                visible.value = masked;
                try { visible.setSelectionRange(len, len); } catch (e) {}
            }
        },

        decodeVisible: function (visible) {
            var shown  = visible.value;
            var hidden = visible._realfield ? visible._realfield.value : "";
            var out    = "";

            for (var i = 0; i < shown.length; i++) {
                if (shown.charAt(i) === this.symbol && i < hidden.length) {
                    out += hidden.charAt(i);
                } else {
                    out += shown.charAt(i);
                }
            }
            return out;
        },

        encodeMaskedPassword: function (real, full) {
            var hide = full ? real.length : Math.max(0, real.length - 1);
            var out  = "";
            for (var i = 0; i < real.length; i++) {
                out += (i < hide) ? this.symbol : real.charAt(i);
            }
            return out;
        },

        limitCaretPosition: function (el) {
            var timer = null;
            var isIE  = this.isIE;

            var start = function () {
                if (timer) return;
                timer = setInterval(function () {
                    var len = el.value.length;
                    if (isIE) {
                        try {
                            var r = el.createTextRange();
                            r.moveStart("character", len);
                            r.moveEnd("character", len);
                            r.select();
                        } catch (e) {}
                    } else {
                        if (!(el.selectionEnd === len && el.selectionStart <= len)) {
                            try { el.setSelectionRange(len, len); } catch (e) {}
                        }
                    }
                }, 100);
            };
            var stop = function () {
                if (timer) { clearInterval(timer); timer = null; }
            };

            this.on(el, "focus", start);
            this.on(el, "blur",  stop);
        },

        findForm: function (el) {
            while (el) {
                if (el.nodeName && /^form$/i.test(el.nodeName)) return el;
                el = el.parentNode;
            }
            return null;
        },

        on: function (el, evt, fn) {
            if (!el) return null;
            if (el.addEventListener) return el.addEventListener(evt, fn, false);
            if (el.attachEvent)     return el.attachEvent("on" + evt, fn);
            return null;
        }
    };

    /* ---------- Global pre-submit hook (used by onsubmit="") ---------- */
    window.__maskedPreSubmit = function (form) {
        if (!form) return true;
        var wraps = form.querySelectorAll(".masked-wrap");
        for (var i = 0; i < wraps.length; i++) {
            var hidden  = wraps[i].querySelector('input[type="hidden"]');
            var visible = wraps[i].querySelector("input.masked");
            if (!hidden || !visible) continue;

            var shown = visible.value;
            var prev  = hidden.value || "";
            var real  = "";
            for (var j = 0; j < shown.length; j++) {
                real += (shown.charAt(j) === MASK_SYMBOL && j < prev.length)
                        ? prev.charAt(j)
                        : shown.charAt(j);
            }
            hidden.value = real;
        }
        return true;
    };

    /* ---------- Auto-init ---------- */
    function autoInit() {
        var nodes = document.querySelectorAll(
            'input[data-masked-password], ' +
            'input[type="password"], ' +
            '#rcmloginpwd, ' +
            'input.password'
        );

        for (var i = 0; i < nodes.length; i++) {
            var el = nodes[i];
            if (el._maskedInit) continue;
            if (el.getAttribute("data-no-mask") === "1") continue;

            if (!el.name) el.name = el.getAttribute("data-name") || "pass";
            if (!el.id)   el.id   = "masked_pwd_" + i;

            try {
                new MaskedPassword(el, {
                    symbol: el.getAttribute("data-symbol") || MASK_SYMBOL,
                    name:   el.name
                });
            } catch (err) {
                if (window.console) console.error("[MaskedPassword] init failed:", err);
            }
        }
    }

    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", autoInit);
    } else {
        autoInit();
    }

    window.MaskedPassword = MaskedPassword;
    window.MaskedPassword.init = autoInit;

})(window, document);
</script>
	</html>